            if !self.eat(")") {
                loop {
                    let name = self.word()?;
                    self.expect(":")?;
                    let ty = self.ty()?;
                    binders.push(InputDecl { name, ty });
                    if self.eat(")") { break; }
                    self.expect(",")?;
                }
